I'll build a minimal Flask app with password hashing, sessions, and rate limiting. What framework/language do you prefer? I'll show Python/Flask here—if you need Node, Django, or something else, say so.

```python
from flask import Flask, request, jsonify
from datetime import datetime, timedelta
from functools import wraps
import bcrypt
import secrets

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

users_db = {}
sessions_db = {}
login_attempts = {}

RATE_LIMIT = 5
RATE_WINDOW = 300  # seconds
SESSION_TIMEOUT = 3600

def hash_password(pwd: str) -> str:
    return bcrypt.hashpw(pwd.encode(), bcrypt.gensalt()).decode()

def verify_password(pwd: str, hashed: str) -> bool:
    return bcrypt.checkpw(pwd.encode(), hashed.encode())

def check_rate_limit(email: str) -> bool:
    now = datetime.utcnow()
    cutoff = now - timedelta(seconds=RATE_WINDOW)
    if email in login_attempts:
        login_attempts[email] = [t for t in login_attempts[email] if t > cutoff]
        if len(login_attempts[email]) >= RATE_LIMIT:
            return False
    return True

def record_attempt(email: str):
    if email not in login_attempts:
        login_attempts[email] = []
    login_attempts[email].append(datetime.utcnow())

def create_session(user_id: str) -> str:
    token = secrets.token_urlsafe(32)
    sessions_db[token] = {
        'user_id': user_id,
        'expires_at': datetime.utcnow() + timedelta(seconds=SESSION_TIMEOUT)
    }
    return token

def get_session(token: str) -> dict | None:
    if token not in sessions_db:
        return None
    sess = sessions_db[token]
    if datetime.utcnow() > sess['expires_at']:
        del sessions_db[token]
        return None
    return sess

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        sess = get_session(token)
        if not sess:
            return {'error': 'Unauthorized'}, 401
        return f(*args, user_id=sess['user_id'], **kwargs)
    return decorated

@app.route('/signup', methods=['POST'])
def signup():
    data = request.json or {}
    email, password = data.get('email', '').strip(), data.get('password', '')

    if not email or not password:
        return {'error': 'Email and password required'}, 400
    if email in users_db:
        return {'error': 'Email exists'}, 409

    users_db[email] = {'password_hash': hash_password(password)}
    return {'user_id': email}, 201

@app.route('/login', methods=['POST'])
def login():
    data = request.json or {}
    email, password = data.get('email', '').strip(), data.get('password', '')

    if not email or not password:
        return {'error': 'Email and password required'}, 400

    if not check_rate_limit(email):
        return {'error': 'Too many attempts'}, 429

    user = users_db.get(email)
    if not user or not verify_password(password, user['password_hash']):
        record_attempt(email)
        return {'error': 'Invalid credentials'}, 401

    login_attempts[email] = []
    token = create_session(email)
    return {'token': token, 'user_id': email}, 200

@app.route('/protected', methods=['GET'])
@require_auth
def protected(user_id):
    return {'user_id': user_id}, 200

@app.route('/logout', methods=['POST'])
def logout():
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    sessions_db.pop(token, None)
    return {}, 200

if __name__ == '__main__':
    with app.test_client() as c:
        print("Signup:", c.post('/signup', json={'email': 'u@x.com', 'password': 'p123'}).status_code)
        r = c.post('/login', json={'email': 'u@x.com', 'password': 'p123'})
        print("Login:", r.status_code, "token:", r.json['token'][:10] + '...')
        tok = r.json['token']
        print("Protected:", c.get('/protected', headers={'Authorization': f'Bearer {tok}'}).status_code)
        for i in range(6):
            c.post('/login', json={'email': 'u@x.com', 'password': 'wrong'})
        print("Rate limit:", c.post('/login', json={'email': 'u@x.com', 'password': 'p123'}).status_code)
